import{_ as t,a0 as o,w as d,s as h,I as n,x as a,a1 as i,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"不可或缺的 Bash 別名 | LCTT x X-CMD","titleTemplate":false,"description":"不可或缺的 Bash 別名 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"不可或缺的 Bash 別名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"不可或缺的 Bash 別名 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190731 Bash aliases you can-t live without","title":"不可或缺的 Bash 別名","tag":"201908","desc":""},"relativePath":"201908/20190731 Bash aliases you can-t live without.md","filePath":"[post].md"}'),r={name:"201908/20190731 Bash aliases you can-t live without.md"};function c(g,s,k,u,b,f){const e=o("Link");return d(),h("div",null,[s[44]||(s[44]=n("h1",{id:"不可或缺的-bash-別名",tabindex:"-1"},[a("不可或缺的 Bash 別名 "),n("a",{class:"header-anchor",href:"#不可或缺的-bash-別名","aria-label":"Permalink to “不可或缺的 Bash 別名”"},"​")],-1)),s[45]||(s[45]=n("blockquote",null,[n("p",null,"厭倦了一遍又一遍地輸入相同的長命令？你覺得在命令列上工作效率低嗎？Bash 別名可以為你創造一個與眾不同的世界。")],-1)),s[46]||(s[46]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/03/095855ip0h0jpi5u9t3r00.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("Bash 別名是一種用新的命令補充或覆蓋 Bash 命令的方法。Bash 別名使用户可以輕鬆地在 ",-1)),i(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:p(()=>[...s[0]||(s[0]=[a("POSIX",-1)])]),_:1}),s[2]||(s[2]=a(" 終端中自定義其體驗。它們通常定義在 ",-1)),s[3]||(s[3]=n("code",null,"$HOME/.bashrc",-1)),s[4]||(s[4]=a(" 或 ",-1)),s[5]||(s[5]=n("code",null,"$HOME/bash_aliases",-1)),s[6]||(s[6]=a(" 中（它是由 ",-1)),s[7]||(s[7]=n("code",null,"$HOME/.bashrc",-1)),s[8]||(s[8]=a(" 加載的）。",-1))]),s[47]||(s[47]=l(`<p>大多數發行版在新用户帳户的默認 <code>.bashrc</code> 文件中至少添加了一些流行的別名。這些可以用來簡單演示 Bash 別名的語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ls=&#39;ls -F&#39;</span></span>
<span class="line"><span>alias ll=&#39;ls -lh&#39;</span></span></code></pre></div><p>但並非所有發行版都附帶預先添加好的別名。如果你想手動添加別名，則必須將它們加載到當前的 Bash 會話中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>否則，你可以關閉終端並重新打開它，以便重新加載其配置文件。</p>`,5)),n("p",null,[s[10]||(s[10]=a("通過 Bash 初始化腳本中定義的那些別名，你可以鍵入 ",-1)),s[11]||(s[11]=n("code",null,"ll",-1)),s[12]||(s[12]=a(" 而得到 ",-1)),s[13]||(s[13]=n("code",null,"ls -l",-1)),s[14]||(s[14]=a(" 的結果，當你鍵入 ",-1)),s[15]||(s[15]=n("code",null,"ls",-1)),s[16]||(s[16]=a(" 時，得到也不是原來的 ",-1)),i(e,{href:"https://opensource.com/article/19/7/master-ls-command"},{default:p(()=>[...s[9]||(s[9]=[a("ls",-1)])]),_:1}),s[17]||(s[17]=a(" 的普通輸出。",-1))]),s[48]||(s[48]=l(`<p>那些別名很棒，但它們只是淺嘗輒止。以下是十大 Bash 別名，一旦你試過它們，你會發現再也不能離開它們。</p><h3 id="首先設置" tabindex="-1">首先設置 <a class="header-anchor" href="#首先設置" aria-label="Permalink to “首先設置”">​</a></h3><p>在開始之前，創建一個名為 <code>~/.bash_aliases</code> 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch ~/.bash_aliases</span></span></code></pre></div><p>然後，確認這些代碼出現在你的 <code>~/.bashrc</code> 文件當中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -e $HOME/.bash_aliases ]; then</span></span>
<span class="line"><span>    source $HOME/.bash_aliases</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>如果你想親自嘗試本文中的任何別名，請將它們輸入到 <code>.bash_aliases</code> 文件當中，然後使用 <code>source ~/.bashrc</code> 命令將它們加載到當前 Bash 會話中。</p><h3 id="按文件大小排序" tabindex="-1">按文件大小排序 <a class="header-anchor" href="#按文件大小排序" aria-label="Permalink to “按文件大小排序”">​</a></h3><p>如果你一開始使用過 GNOME 中的 Nautilus、MacOS 中的 Finder 或 Windows 中的資源管理器等 GUI 文件管理器，那麼你很可能習慣了按文件大小排序文件列表。你也可以在終端上做到這一點，但這條命令不是很簡潔。</p><p>將此別名添加到 GNU 系統上的配置中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lt=&#39;ls --human-readable --size -1 -S --classify&#39;</span></span></code></pre></div><p>此別名將 <code>lt</code> 替換為 <code>ls</code> 命令，該命令在單個列中顯示每個項目的大小，然後按大小對其進行排序，並使用符號表示文件類型。加載新別名，然後試一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span>
<span class="line"><span>$ lt</span></span>
<span class="line"><span>total 344K</span></span>
<span class="line"><span>140K configure*</span></span>
<span class="line"><span> 44K aclocal.m4</span></span>
<span class="line"><span> 36K LICENSE</span></span>
<span class="line"><span> 32K config.status*</span></span>
<span class="line"><span> 24K Makefile</span></span>
<span class="line"><span> 24K Makefile.in</span></span>
<span class="line"><span> 12K config.log</span></span>
<span class="line"><span>8.0K README.md</span></span>
<span class="line"><span>4.0K info.slackermedia.Git-portal.json</span></span>
<span class="line"><span>4.0K git-portal.spec</span></span>
<span class="line"><span>4.0K flatpak.path.patch</span></span>
<span class="line"><span>4.0K Makefile.am*</span></span>
<span class="line"><span>4.0K dot-gitlab.ci.yml</span></span>
<span class="line"><span>4.0K configure.ac*</span></span>
<span class="line"><span>   0 autom4te.cache/</span></span>
<span class="line"><span>   0 share/</span></span>
<span class="line"><span>   0 bin/</span></span>
<span class="line"><span>   0 install-sh@</span></span>
<span class="line"><span>   0 compile@</span></span>
<span class="line"><span>   0 missing@</span></span>
<span class="line"><span>   0 COPYING@</span></span></code></pre></div><p>在 MacOS 或 BSD 上，<code>ls</code> 命令沒有相同的選項，因此這個別名可以改為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lt=&#39;du -sh * | sort -h&#39;</span></span></code></pre></div><p>這個版本的結果稍有不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du -sh * | sort -h</span></span>
<span class="line"><span>0       compile</span></span>
<span class="line"><span>0       COPYING</span></span>
<span class="line"><span>0       install-sh</span></span>
<span class="line"><span>0       missing</span></span>
<span class="line"><span>4.0K    configure.ac</span></span>
<span class="line"><span>4.0K    dot-gitlab.ci.yml</span></span>
<span class="line"><span>4.0K    flatpak.path.patch</span></span>
<span class="line"><span>4.0K    git-portal.spec</span></span>
<span class="line"><span>4.0K    info.slackermedia.Git-portal.json</span></span>
<span class="line"><span>4.0K    Makefile.am</span></span>
<span class="line"><span>8.0K    README.md</span></span>
<span class="line"><span>12K     config.log</span></span>
<span class="line"><span>16K     bin</span></span>
<span class="line"><span>24K     Makefile</span></span>
<span class="line"><span>24K     Makefile.in</span></span>
<span class="line"><span>32K     config.status</span></span>
<span class="line"><span>36K     LICENSE</span></span>
<span class="line"><span>44K     aclocal.m4</span></span>
<span class="line"><span>60K     share</span></span>
<span class="line"><span>140K    configure</span></span>
<span class="line"><span>476K    autom4te.cache</span></span></code></pre></div><p>實際上，即使在 Linux上，上面這個命令也很有用，因為使用 <code>ls</code> 列出的目錄和符號鏈接的大小為 0，這可能不是你真正想要的信息。使用哪個看你自己的喜好。</p><p><em>感謝 Brad Alexander 提供的這個別名的思路。</em></p><h3 id="只查看掛載的驅動器" tabindex="-1">只查看掛載的驅動器 <a class="header-anchor" href="#只查看掛載的驅動器" aria-label="Permalink to “只查看掛載的驅動器”">​</a></h3><p><code>mount</code> 命令過去很簡單。只需一個命令，你就可以獲得計算機上所有已掛載的文件系統的列表，它經常用於概覽連接到工作站有哪些驅動器。在過去看到超過三、四個條目就會令人印象深刻，因為大多數計算機沒有那麼多的 USB 端口，因此這個結果還是比較好查看的。</p><p>現在計算機有點複雜，有 LVM、物理驅動器、網絡存儲和虛擬文件系統，<code>mount</code> 的結果就很難一目瞭然：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sysfs on /sys type sysfs (rw,nosuid,nodev,noexec,relatime,seclabel)</span></span>
<span class="line"><span>proc on /proc type proc (rw,nosuid,nodev,noexec,relatime)</span></span>
<span class="line"><span>devtmpfs on /dev type devtmpfs (rw,nosuid,seclabel,size=8131024k,nr_inodes=2032756,mode=755)</span></span>
<span class="line"><span>securityfs on /sys/kernel/security type securityfs (rw,nosuid,nodev,noexec,relatime)</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>/dev/nvme0n1p2 on /boot type ext4 (rw,relatime,seclabel)</span></span>
<span class="line"><span>/dev/nvme0n1p1 on /boot/efi type vfat (rw,relatime,fmask=0077,dmask=0077,codepage=437,iocharset=ascii,shortname=winnt,errors=remount-ro)</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>gvfsd-fuse on /run/user/100977/gvfs type fuse.gvfsd-fuse (rw,nosuid,nodev,relatime,user_id=100977,group_id=100977)</span></span>
<span class="line"><span>/dev/sda1 on /run/media/seth/pocket type ext4 (rw,nosuid,nodev,relatime,seclabel,uhelper=udisks2)</span></span>
<span class="line"><span>/dev/sdc1 on /run/media/seth/trip type ext4 (rw,nosuid,nodev,relatime,seclabel,uhelper=udisks2)</span></span>
<span class="line"><span>binfmt_misc on /proc/sys/fs/binfmt_misc type binfmt_misc (rw,relatime)</span></span></code></pre></div><p>要解決這個問題，試試這個別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias mnt=&#39;mount | awk -F&#39; &#39; &#39;{ printf &quot;%s\\t%s\\n&quot;,$1,$3; }&#39; | column -t | egrep ^/dev/ | sort&#39;</span></span></code></pre></div><p>此別名使用 <code>awk</code> 按列解析 <code>mount</code> 的輸出，將輸出減少到你可能想要查找的內容（掛載了哪些硬盤驅動器，而不是文件系統）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mnt</span></span>
<span class="line"><span>/dev/mapper/fedora-root  /</span></span>
<span class="line"><span>/dev/nvme0n1p1           /boot/efi</span></span>
<span class="line"><span>/dev/nvme0n1p2           /boot</span></span>
<span class="line"><span>/dev/sda1                /run/media/seth/pocket</span></span>
<span class="line"><span>/dev/sdc1                /run/media/seth/trip</span></span></code></pre></div><p>在 MacOS 上，<code>mount</code> 命令不提供非常詳細的輸出，因此這個別名可能過度精簡了。但是，如果你更喜歡簡潔的報告，請嘗試以下方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias mnt=&#39;mount | grep -E ^/dev | column -t&#39;</span></span></code></pre></div><p>結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mnt</span></span>
<span class="line"><span>/dev/disk1s1  on  /                (apfs,  local,  journaled)</span></span>
<span class="line"><span>/dev/disk1s4  on  /private/var/vm  (apfs,  local,  noexec,     journaled,  noatime,  nobrowse)</span></span></code></pre></div><h3 id="在你的-grep-歷史中查找命令" tabindex="-1">在你的 grep 歷史中查找命令 <a class="header-anchor" href="#在你的-grep-歷史中查找命令" aria-label="Permalink to “在你的 grep 歷史中查找命令”">​</a></h3><p>有時你好不容易弄清楚瞭如何在終端完成某件事，並覺得自己永遠不會忘記你剛學到的東西。然後，一個小時過去之後你就完全忘記了你做了什麼。</p><p>搜索 Bash 歷史記錄是每個人不時要做的事情。如果你確切地知道要搜索的內容，可以使用 <code>Ctrl + R</code> 對歷史記錄進行反向搜索，但有時你無法記住要查找的確切命令。</p><p>這是使該任務更容易的別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias gh=&#39;history|grep&#39;</span></span></code></pre></div><p>這是如何使用的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gh bash</span></span>
<span class="line"><span>482 cat ~/.bashrc | grep _alias</span></span>
<span class="line"><span>498 emacs ~/.bashrc</span></span>
<span class="line"><span>530 emacs ~/.bash_aliases</span></span>
<span class="line"><span>531 source ~/.bashrc</span></span></code></pre></div><h3 id="按修改時間排序" tabindex="-1">按修改時間排序 <a class="header-anchor" href="#按修改時間排序" aria-label="Permalink to “按修改時間排序”">​</a></h3><p>每個星期一都會這樣：你坐在你的電腦前開始工作，你打開一個終端，你發現你已經忘記了上週五你在做什麼。你需要的是列出最近修改的文件的別名。</p><p>你可以使用 <code>ls</code> 命令創建別名，以幫助你找到上次離開的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias left=&#39;ls -t -1&#39;</span></span></code></pre></div><p>輸出很簡單，但如果你願意，可以使用 <code>--long</code> 選項擴展它。這個別名列出的顯示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ left</span></span>
<span class="line"><span>demo.jpeg</span></span>
<span class="line"><span>demo.xcf</span></span>
<span class="line"><span>design-proposal.md</span></span>
<span class="line"><span>rejects.txt</span></span>
<span class="line"><span>brainstorm.txt</span></span>
<span class="line"><span>query-letter.xml</span></span></code></pre></div><h3 id="文件計數" tabindex="-1">文件計數 <a class="header-anchor" href="#文件計數" aria-label="Permalink to “文件計數”">​</a></h3><p>如果你需要知道目錄中有多少文件，那麼該解決方案是 UNIX 命令構造的最典型示例之一：使用 <code>ls</code> 命令列出文件，用<code>-1</code> 選項將其輸出控制為只有一列，然後輸出到 <code>wc</code>（單詞計數）命令的管道，以計算有多少行。</p><p>這是 UNIX 理念如何允許用户使用小型的系統組件構建自己的解決方案的精彩演示。如果你碰巧每天都要做幾次，這個命令組合也要輸入很多字母，如果沒有使用 <code>-R</code> 選項，它就不能用於目錄，這會為輸出引入新行並導致無用的結果。</p><p>而這個別名使這個過程變得簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias count=&#39;find . -type f | wc -l&#39;</span></span></code></pre></div><p>這個別名會計算文件，忽略目錄，但<strong>不會</strong>忽略目錄的內容。如果你有一個包含兩個目錄的項目文件夾，每個目錄包含兩個文件，則該別名將返回 4，因為整個項目中有 4 個文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>foo   bar</span></span>
<span class="line"><span>$ count</span></span>
<span class="line"><span>4</span></span></code></pre></div><h3 id="創建-python-虛擬環境" tabindex="-1">創建 Python 虛擬環境 <a class="header-anchor" href="#創建-python-虛擬環境" aria-label="Permalink to “創建 Python 虛擬環境”">​</a></h3><p>你用 Python 編程嗎？</p><p>你用 Python 編寫了很多程序嗎？</p><p>如果是這樣，那麼你就知道創建 Python 虛擬環境至少需要 53 次擊鍵。</p><p>這個數字裏有 49 次是多餘的，它很容易被兩個名為 <code>ve</code> 和 <code>va</code> 的新別名所解決：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ve=&#39;python3 -m venv ./venv&#39;</span></span>
<span class="line"><span>alias va=&#39;source ./venv/bin/activate&#39;</span></span></code></pre></div><p>運行 <code>ve</code> 會創建一個名為 <code>venv</code> 的新目錄，其中包含 Python 3 的常用虛擬環境文件系統。<code>va</code> 別名在當前 shell 中的激活該環境：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd my-project</span></span>
<span class="line"><span>$ ve</span></span>
<span class="line"><span>$ va</span></span>
<span class="line"><span>(venv) $</span></span></code></pre></div><h3 id="增加一個複製進度條" tabindex="-1">增加一個複製進度條 <a class="header-anchor" href="#增加一個複製進度條" aria-label="Permalink to “增加一個複製進度條”">​</a></h3><p>每個人都會吐槽進度條，因為它們似乎總是不合時宜。然而，在內心深處，我們似乎都想要它們。UNIX 的 <code>cp</code> 命令沒有進度條，但它有一個 <code>-v</code> 選項用於顯示詳細信息，它回顯了複製的每個文件名到終端。這是一個相當不錯的技巧，但是當你複製一個大文件並且想要了解還有多少文件尚未傳輸時，它的作用就沒那麼大了。</p><p><code>pv</code> 命令可以在複製期間提供進度條，但它並不常用。另一方面，<code>rsync</code> 命令包含在幾乎所有的 POSIX 系統的默認安裝中，並且它被普遍認為是遠程和本地複製文件的最智能方法之一。</p><p>更好的是，它有一個內置的進度條。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias cpv=&#39;rsync -ah --info=progress2&#39;</span></span></code></pre></div><p>像使用 <code>cp</code> 命令一樣使用此別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cpv bigfile.flac /run/media/seth/audio/</span></span>
<span class="line"><span>          3.83M 6%  213.15MB/s    0:00:00 (xfr#4, to-chk=0/4)</span></span></code></pre></div><p>使用此命令的一個有趣的副作用是 <code>rsync</code> 無需 <code>-r</code> 標誌就可以複製文件和目錄，而 <code>cp</code> 則需要。</p><h3 id="避免意外刪除" tabindex="-1">避免意外刪除 <a class="header-anchor" href="#避免意外刪除" aria-label="Permalink to “避免意外刪除”">​</a></h3><p>你不應該使用 <code>rm</code> 命令。<code>rm</code> 手冊甚至這樣説：</p><blockquote><p><strong>警告：</strong>如果使用 <code>rm</code> 刪除文件，通常可以恢復該文件的內容。如果你想要更加確保內容真正無法恢復，請考慮使用 <code>shred</code>。</p></blockquote><p>如果要刪除文件，則應將文件移動到“廢紙簍”，就像使用桌面時一樣。</p>`,71)),n("p",null,[s[19]||(s[19]=a("POSIX 使這很簡單，因為垃圾桶是文件系統中可訪問的一個實際位置。該位置可能會發生變化，具體取決於你的平台：在 ",-1)),i(e,{href:"https://www.freedesktop.org/wiki/"},{default:p(()=>[...s[18]||(s[18]=[a("FreeDesktop",-1)])]),_:1}),s[20]||(s[20]=a(" 上，“垃圾桶”位於 ",-1)),s[21]||(s[21]=n("code",null,"~/.local/share/Trash",-1)),s[22]||(s[22]=a("，而在 MacOS 上則是 ",-1)),s[23]||(s[23]=n("code",null,"~/.Trash",-1)),s[24]||(s[24]=a("，但無論如何，它只是一個目錄，你可以將文件藏在那個看不見的地方，直到你準備永久刪除它們為止。",-1))]),s[49]||(s[49]=l(`<p>這個簡單的別名提供了一種從終端將文件扔進垃圾桶的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias tcn=&#39;mv --force -t ~/.local/share/Trash &#39;</span></span></code></pre></div><p>該別名使用一個鮮為人知的 <code>mv</code> 標誌（<code>-t</code>），使你能夠提供作為最終移動目標的參數，而忽略了首先列出要移動的文件的通常要求。現在，你可以使用新命令將文件和文件夾移動到系統垃圾桶：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>foo  bar</span></span>
<span class="line"><span>$ tcn foo</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>bar</span></span></code></pre></div><p>現在文件已“消失”，只有在你一頭冷汗的時候才意識到你還需要它。此時，你可以從系統垃圾桶中搶救該文件；這肯定可以給 Bash 和 <code>mv</code> 開發人員提供一些幫助。</p>`,5)),n("p",null,[s[26]||(s[26]=n("strong",null,"注意：",-1)),s[27]||(s[27]=a("如果你需要一個具有更好的 FreeDesktop 兼容性的更強大的垃圾桶命令，請參閲 ",-1)),i(e,{href:"https://gitlab.com/trashy/trashy"},{default:p(()=>[...s[25]||(s[25]=[a("Trashy",-1)])]),_:1}),s[28]||(s[28]=a("。",-1))]),s[50]||(s[50]=l(`<h3 id="簡化-git-工作流" tabindex="-1">簡化 Git 工作流 <a class="header-anchor" href="#簡化-git-工作流" aria-label="Permalink to “簡化 Git 工作流”">​</a></h3><p>每個人都有自己獨特的工作流程，但無論如何，通常都會有重複的任務。如果你經常使用 Git，那麼你可能會發現自己經常重複的一些操作序列。也許你會發現自己回到主分支並整天一遍又一遍地拉取最新的變化，或者你可能發現自己創建了標籤然後將它們推到遠端，抑或可能完全是其它的什麼東西。</p><p>無論讓你厭倦一遍遍輸入的 Git 魔咒是什麼，你都可以通過 Bash 別名減輕一些痛苦。很大程度上，由於它能夠將參數傳遞給鈎子，Git 擁有着豐富的內省命令，可以讓你不必在 Bash 中執行那些醜陋冗長的命令。</p><p>例如，雖然你可能很難在 Bash 中找到項目的頂級目錄（就 Bash 而言，它是一個完全隨意的名稱，因為計算機的絕對頂級是根目錄），但 Git 可以通過簡單的查詢找到項目的頂級目錄。如果你研究過 Git 鈎子，你會發現自己能夠找到 Bash 一無所知的各種信息，而你可以利用 Bash 別名來利用這些信息。</p><p>這是一個來查找 Git 項目的頂級目錄的別名，無論你當前在哪個項目中工作，都可以將目錄改變為頂級目錄，切換到主分支，並執行 Git 拉取：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias startgit=&#39;cd \`git rev-parse --show-toplevel\` &amp;&amp; git checkout master &amp;&amp; git pull&#39;</span></span></code></pre></div><p>這種別名絕不是一個普遍有用的別名，但它演示了一個相對簡單的別名如何能夠消除大量繁瑣的導航、命令和等待提示。</p><p>一個更簡單，可能更通用的別名將使你返回到 Git 項目的頂級目錄。這個別名非常有用，因為當你在一個項目上工作時，該項目或多或少會成為你的“臨時家目錄”。它應該像回家一樣簡單，就像回你真正的家一樣，這裏有一個別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias cg=&#39;cd \`git rev-parse --show-toplevel\`&#39;</span></span></code></pre></div><p>現在，命令 <code>cg</code> 將你帶到 Git 項目的頂部，無論你下潛的目錄結構有多深。</p><h3 id="切換目錄並同時查看目錄內容" tabindex="-1">切換目錄並同時查看目錄內容 <a class="header-anchor" href="#切換目錄並同時查看目錄內容" aria-label="Permalink to “切換目錄並同時查看目錄內容”">​</a></h3><p>（據稱）曾經一位著名科學家提出過，我們可以通過收集極客輸入 <code>cd</code> 後跟 <code>ls</code> 消耗的能量來解決地球上的許多能量問題。</p><p>這是一種常見的用法，因為通常當你更改目錄時，你都會有查看周圍的內容的衝動或需要。</p><p>但是在你的計算機的目錄樹中移動並不一定是一個走走停停的過程。</p><p>這是一個作弊，因為它根本不是別名，但它是探索 Bash 功能的一個很好的藉口。雖然別名非常適合快速替換一個命令，但 Bash 也允許你在 <code>.bashrc</code> 文件中添加本地函數（或者你加載到 <code>.bashrc</code> 中的單獨函數文件，就像你的別名文件一樣）。</p><p>為了保持模組化，創建一個名為 <code>~/.bash_functions</code> 的新文件，然後讓你的 <code>.bashrc</code> 加載它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -e $HOME/.bash_functions ]; then</span></span>
<span class="line"><span>    source $HOME/.bash_functions</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>在該函數文件中，添加這些代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function cl() {</span></span>
<span class="line"><span>    DIR=&quot;$*&quot;;</span></span>
<span class="line"><span>        # if no DIR given, go home</span></span>
<span class="line"><span>        if [ $# -lt 1 ]; then</span></span>
<span class="line"><span>                DIR=$HOME;</span></span>
<span class="line"><span>    fi;</span></span>
<span class="line"><span>    builtin cd &quot;\${DIR}&quot; &amp;amp;&amp;amp; \\</span></span>
<span class="line"><span>    # use your preferred ls command</span></span>
<span class="line"><span>        ls -F --color=auto</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>將函數加載到 Bash 會話中，然後嘗試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bash_functions</span></span>
<span class="line"><span>$ cl Documents</span></span>
<span class="line"><span>foo bar baz</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/seth/Documents</span></span>
<span class="line"><span>$ cl ..</span></span>
<span class="line"><span>Desktop  Documents  Downloads</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/seth</span></span></code></pre></div><p>函數比別名更靈活，但有了這種靈活性，你就有責任確保代碼有意義並達到你的期望。別名是簡單的，所以要保持簡單而有用。要正式修改 Bash 的行為，請使用保存到 <code>PATH</code> 環境變量中某個位置的函數或自定義的 shell 腳本。</p><p>附註，有一些巧妙的奇技淫巧來實現 <code>cd</code> 和 <code>ls</code> 序列作為別名，所以如果你足夠耐心，那麼即使是一個簡單的別名也永無止限。</p><h3 id="開始別名化和函數化吧" tabindex="-1">開始別名化和函數化吧 <a class="header-anchor" href="#開始別名化和函數化吧" aria-label="Permalink to “開始別名化和函數化吧”">​</a></h3><p>可以定製你的環境使得 Linux 變得如此有趣，提高效率使得 Linux 可以改變生活。開始使用簡單的別名，進而使用函數，並在評論中發佈你必須擁有的別名！</p><hr>`,26)),n("p",null,[s[30]||(s[30]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/7/bash-aliases"},{default:p(()=>[...s[29]||(s[29]=[a("https://opensource.com/article/19/7/bash-aliases",-1)])]),_:1})]),n("p",null,[s[35]||(s[35]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[31]||(s[31]=[a("Seth Kenlon",-1)])]),_:1}),s[36]||(s[36]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[32]||(s[32]=[a("lujun9972",-1)])]),_:1}),s[37]||(s[37]=a(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[33]||(s[33]=[a("wxy",-1)])]),_:1}),s[38]||(s[38]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[34]||(s[34]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[41]||(s[41]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[39]||(s[39]=[a("LCTT",-1)])]),_:1}),s[42]||(s[42]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[40]||(s[40]=[a("Linux中國",-1)])]),_:1}),s[43]||(s[43]=a(" 榮譽推出",-1))])])}const C=t(r,[["render",c]]);export{v as __pageData,C as default};
